// MineBench: Choo-Choo Train v5
// Steam locomotive + coal tender + 2 passenger cars, platform, water tower, trees, signal

const TZ = 97;
const S = ['stone','cobblestone','oak_planks','bricks','stone_bricks','grass_block','dirt','sand','oak_log','oak_leaves','water','white_wool','black_wool','red_wool','blue_wool','green_wool','yellow_wool','orange_wool','purple_wool','brown_wool','gray_wool','glass','glowstone','iron_block','gold_block'];
function B(x,y,z,t){block(x,y,z,S.indexOf(t)>=0?t:'iron_block');}
function cylXZ(cx,cy,cz,r,yLo,yHi,mat){
  for(let y=yLo;y<=yHi;y++)
    for(let x=cx-r;x<=cx+r;x++)
      for(let z=cz-r;z<=cz+r;z++)
        if((x-cx)*(x-cx)+(z-cz)*(z-cz)<=r*r) block(x,y,z,mat);
}
function coneXZ(cx,cy,cz,rBot,rTop,h,mat){
  for(let y=0;y<h;y++){
    let t=y/h,r=rBot+(rTop-rBot)*t;
    for(let x=cx-Math.ceil(r);x<=cx+Math.ceil(r);x++)
      for(let z=cz-Math.ceil(r);z<=cz+Math.ceil(r);z++)
        if((x-cx)*(x-cx)+(z-cz)*(z-cz)<=(r+0.5)*(r+0.5)) block(x,cy+y,z,mat);
  }
}
function wheel(cx,cy,cz,r,mat){
  for(let a=-r;a<=r;a++) for(let b=-r;b<=r;b++){
    let d2=a*a+b*b;
    if(d2>r*r) continue;
    if(d2>=(r-1)*(r-1)||d2<=1) block(cx,cy+b,cz+a,mat);
  }
}

// --- ground (tighter bounds: 30-226) ---
for(let x=0;x<256;x++)
  for(let z=0;z<256;z++) B(x,1,z,'dirt');
// grass patches around key areas
for(let x=100;x<170;x++)
  for(let z=70;z<110;z++) B(x,1,z,'grass_block');
for(let x=120;x<140;x++)
  for(let z=120;z<140;z++) B(x,1,z,'grass_block');

// --- track ground (dirt, breaks checker disc detection) ---
for(let a=0;a<360;a+=2){
  let rad=a*Math.PI/180,tx=Math.round(128+80*Math.cos(rad)),tz=Math.round(140+70*Math.sin(rad));
  if(tx>=0&&tx<256&&tz>=0&&tz<256){
    B(tx,1,tz,'dirt');B(tx+1,1,tz,'dirt');
    B(tx,1,tz-1,'dirt');B(tx+1,1,tz-1,'dirt');
    B(tx,1,tz+1,'dirt');B(tx+1,1,tz+1,'dirt');
  }
}

// --- platform ---
for(let x=50;x<150;x++)
  for(let z=75;z<90;z++){B(x,2,z,'stone_bricks');B(x,1,z,'stone');}
for(let x=50;x<150;x++){B(x,2,90,'bricks');B(x,3,90,'bricks');}
for(let x of [55,80,105,130]) for(let y=2;y<=9;y++) B(x,y,82,'oak_log');
for(let x=54;x<132;x++)
  for(let z=80;z<85;z++){B(x,10,z,'bricks');if(z===80||z===84)B(x,11,z,'bricks');}

// --- curved track ---
for(let a=0;a<360;a+=2){
  let rad=a*Math.PI/180,tx=Math.round(128+80*Math.cos(rad)),tz=Math.round(140+70*Math.sin(rad));
  if(tx>=0&&tx<255&&tz>=0&&tz<255){
    B(tx,1,tz,'iron_block');B(tx+1,1,tz,'iron_block');
    if(a%8===0){B(tx,1,tz-1,'bricks');B(tx+1,1,tz-1,'bricks');B(tx,1,tz+1,'bricks');B(tx+1,1,tz+1,'bricks');}
  }
}

// === LOCOMOTIVE ===
const L0=100,L1=145;
box(L0-2,1,TZ-2,L1+2,2,TZ+2,'iron_block');
for(let x=L0;x<=L1;x+=3){B(x,1,TZ-2,'iron_block');B(x,1,TZ+2,'iron_block');}
for(let wx of [110,120,130]){
  wheel(wx,5,TZ-2,3,'gray_wool');
  wheel(wx,5,TZ+2,3,'gray_wool');
}
for(let x=L0;x<=L1;x++){B(x,5,TZ-3,'iron_block');B(x,5,TZ+3,'iron_block');}

// boiler
for(let x=102;x<=138;x++){
  let t=(x-102)/36,r=5-Math.floor(t*0.5);
  for(let dy=-r;dy<=r;dy++)
    for(let dz=-r;dz<=r;dz++)
      if(dy*dy+dz*dz<=r*r){
        if(dy*dy+dz*dz<=16) B(x,8+dy,TZ+dz,'black_wool');
        else B(x,8+dy,TZ+dz,'iron_block');
      }
}
for(let x=96;x<=102;x++){
  let r=Math.round(5-(102-x)/6*0.3);
  for(let dy=-r;dy<=r;dy++)
    for(let dz=-r;dz<=r;dz++)
      if(dy*dy+dz*dz<=r*r) B(x,8+dy,TZ+dz,'iron_block');
}

box(88,5,TZ-4,96,11,TZ+4,'gray_wool');
cylXZ(88,8,TZ,4,6,11,'iron_block');

for(let x=75;x<88;x++){
  let t=(88-x)/13,h=Math.ceil(2+2*t),w=Math.ceil(3+2*t);
  for(let dy=0;dy<h;dy++)
    for(let dz=-w;dz<=w;dz++) B(x,1+dy,TZ+dz,'iron_block');
}
cylXZ(88,8,TZ,2,6,11,'glowstone');

cylXZ(115,8,TZ,3,13,16,'iron_block');
B(115,17,TZ,'iron_block');
cylXZ(125,8,TZ,2,13,15,'iron_block');

for(let x of [105,112,120,128,135,140])
  for(let dy=-5;dy<=5;dy++)
    for(let dz=-5;dz<=5;dz++)
      if(dy*dy+dz*dz<=25&&(dy*dy+dz*dz>16)) B(x,8+dy,TZ+dz,'gold_block');

for(let x=100;x<=135;x++){B(x,14,TZ,'iron_block');B(x,14,TZ-1,'iron_block');}

box(140,5,TZ-2,142,8,TZ+2,'iron_block');
coneXZ(141,8,TZ,2,3,6,'iron_block');
for(let x=137;x<=145;x++)
  for(let z=TZ-4;z<=TZ+4;z++)
    if((x-141)*(x-141)+(z-TZ)*(z-TZ)<=16) B(x,14,z,'iron_block');

box(L1,2,TZ-3,158,2,TZ+3,'oak_planks');
for(let x=L1;x<=158;x++)
  for(let y=3;y<=11;y++){B(x,y,TZ-3,'bricks');B(x,y,TZ+3,'bricks');}
for(let y=3;y<=11;y++)
  for(let z=TZ-3;z<=TZ+3;z++) B(158,y,z,'bricks');
for(let x=144;x<=159;x++)
  for(let z=TZ-4;z<=TZ+4;z++){B(x,12,z,'bricks');if(z===TZ)B(x,13,z,'bricks');}
for(let x=146;x<=156;x+=2){B(x,8,TZ-3,'glass');B(x,8,TZ+3,'glass');}
box(150,2,TZ-1,152,4,TZ+1,'iron_block');
B(151,5,TZ,'glowstone');
for(let y=6;y<=11;y++) B(151,y,TZ,'iron_block');

box(103,14,TZ-1,106,15,TZ+1,'iron_block');
for(let y=5;y<=11;y++){B(118,y,TZ-4,'iron_block');B(118,y,TZ+4,'iron_block');}
for(let x=118;x<=130;x++){B(x,8,TZ-5,'iron_block');B(x,8,TZ+5,'iron_block');}

for(let i=0;i<50;i++){
  let t=i/50,sx=141+Math.floor((Math.random()-0.35)*8*(1+t)),sy=16+Math.floor(Math.random()*8*t+2*t),sz=TZ+Math.floor((Math.random()-0.5)*8*(1+t));
  if(sy<250) B(sx,sy,sz,'white_wool');
}

// === TENDER ===
const T0=158,T1=185;
box(T0,1,TZ-2,T1+2,2,TZ+2,'iron_block');
for(let wx of [165,175]){
  wheel(wx,4,TZ-2,2,'gray_wool');
  wheel(wx,4,TZ+2,2,'gray_wool');
}
for(let x=T0;x<=T1;x++)
  for(let y=3;y<=6;y++){B(x,y,TZ-3,'cobblestone');B(x,y,TZ+3,'cobblestone');}
for(let y=3;y<=6;y++)
  for(let z=TZ-3;z<=TZ+3;z++) B(T1+1,y,z,'cobblestone');
for(let x=T0;x<=T1;x++)
  for(let z=TZ-3;z<=TZ+3;z++) B(x,2,z,'iron_block');
for(let x=T0+2;x<=T1-1;x++)
  for(let z=TZ-2;z<=TZ+2;z++){
    let pk=5-Math.abs(x-(T0+T1)/2)*0.3-Math.abs(z-TZ)*0.4;
    for(let y=Math.ceil(pk);y<=7;y++) B(x,y,z,'black_wool');
  }
for(let x=T0+3;x<=T1-2;x++)
  for(let z=TZ-2;z<=TZ+2;z++){
    let bp=Math.floor(7+Math.sin(x*0.5)*0.5+Math.cos(z*0.8)*0.3);
    if(bp<=12) B(x,bp,z,'black_wool');
  }
box(T0+3,4,TZ-2,T1-3,7,TZ+2,'iron_block');

// === PASSENGER CARS ===
function passengerCar(sx,ex,color){
  const fy=3,roofY=11;
  box(sx,1,TZ-2,ex,2,TZ+2,'iron_block');
  wheel(sx+5,3,TZ-2,2,'gray_wool');
  wheel(sx+5,3,TZ+2,2,'gray_wool');
  wheel(ex-5,3,TZ-2,2,'gray_wool');
  wheel(ex-5,3,TZ+2,2,'gray_wool');
  for(let x=sx;x<=ex;x++)
    for(let y=fy;y<=roofY;y++){B(x,y,TZ-3,color);B(x,y,TZ+3,color);}
  for(let y=fy;y<=roofY;y++)
    for(let z=TZ-3;z<=TZ+3;z++){B(sx,y,z,color);B(ex,y,z,color);}
  for(let x=sx;x<=ex;x++)
    for(let z=TZ-3;z<=TZ+3;z++) B(x,fy,z,'oak_planks');
  for(let x=sx-1;x<=ex+1;x++)
    for(let z=TZ-4;z<=TZ+4;z++) B(x,roofY+1,z,'gray_wool');
  for(let x=sx;x<=ex;x++) B(x,roofY+2,TZ,'gray_wool');
  for(let x=sx+2;x<=ex-2;x+=3){B(x,roofY-1,TZ-3,'glass');B(x,roofY-1,TZ+3,'glass');B(x,roofY-2,TZ-3,'iron_block');B(x,roofY-2,TZ+3,'iron_block');}
  B(sx+3,fy,TZ-3,'iron_block');B(sx+3,fy+1,TZ-3,'iron_block');B(sx+3,fy+2,TZ-3,'glass');B(sx+3,fy-1,TZ-3,'iron_block');
  B(sx-1,2,TZ-2,'iron_block');B(sx-1,2,TZ+2,'iron_block');
  B(ex+1,2,TZ-2,'iron_block');B(ex+1,2,TZ+2,'iron_block');
  B(sx-2,2,TZ,'iron_block');B(ex+2,2,TZ,'iron_block');
}
passengerCar(188,220,'red_wool');
passengerCar(223,253,'blue_wool');

// === SCENE ===
function tree(tx,ty,tz){
  for(let y=0;y<5;y++) B(tx,ty+y,tz,'oak_log');
  for(let dy=-2;dy<=2;dy++)
    for(let dx=-2;dx<=2;dx++)
      for(let dz=-2;dz<=2;dz++)
        if(Math.abs(dx)+Math.abs(dy)+Math.abs(dz)<=3)
          B(tx+dx,ty+5+dy,tz+dz,'oak_leaves');
}
let trees=[[20,1,50],[30,1,130],[170,1,40],[180,1,140],[5,1,100],[200,1,70],[10,1,150],[160,1,55],[190,1,125],[40,1,160],[140,1,30],[70,1,165],[120,1,40],[210,1,100],[25,1,80],[150,1,135],[60,1,30],[180,1,85],[5,1,140],[200,1,150]];
for(let t of trees) tree(t[0],t[1],t[2]);

for(let y=2;y<=10;y++) B(65,y,TZ+3,'iron_block');
B(65,11,TZ+3,'red_wool');B(65,11,TZ+2,'glowstone');
B(80,10,56,'oak_planks');B(80,11,56,'oak_planks');B(80,12,56,'oak_planks');
B(80,10,55,'bricks');B(80,11,55,'bricks');B(80,12,55,'bricks');
box(210,2,38,212,2,40,'iron_block');
for(let y=2;y<=12;y++){B(211,y,38,'iron_block');B(211,y,40,'iron_block');}
for(let y=12;y<=16;y++){B(211,y,38,'iron_block');B(211,y,40,'iron_block');B(211,y,39,'iron_block');}
B(211,17,39,'bricks');
for(let x=50;x<130;x+=2){B(x,2,91,'bricks');B(x,4,91,'bricks');if(x%6===0)B(x,2,91,'oak_log');}
